    async function claimDocument(targetDocNo: any) {

    	let found: any = false

    	for (let pageIndex = 1; pageIndex <= 10; pageIndex++) {

    		await WebUI.comment("Checking page " + pageIndex + " for Document No: " + targetDocNo)

    		let targetRow: any = new TestObject("targetRow_" + targetDocNo)
    		targetRow.addProperty("xpath", ConditionType.EQUALS,
    			"//tbody[contains(@id,'taskListGroupId_data')]//tr[td[normalize-space()='" + targetDocNo + "']]"
    		)

    		if (await WebUI.verifyElementPresent(targetRow, 3, FailureHandling.OPTIONAL)) {

    			let claimBtn: any = new TestObject("claimBtn_" + targetDocNo)
    			claimBtn.addProperty("xpath", ConditionType.EQUALS,
    				"//tbody[contains(@id,'taskListGroupId_data')]//tr[td[normalize-space()='" + targetDocNo + "']]//span[normalize-space()='Claim']/ancestor::button"
    			)

    			await WebUI.waitForElementClickable(claimBtn, 20)
    			await c(claimBtn, 20)
    			await waitBlockUI(30)
    			await WebUI.delay(1)

    			found = true
    			break
    		}

    		if (pageIndex < 10) {
    			let nextIndex: any = pageIndex + 1

    			let nextPage: any = new TestObject("page_" + nextIndex)
    			nextPage.addProperty("xpath", ConditionType.EQUALS,
    				"(//span[contains(@class,'ui-paginator-pages')]/span[normalize-space()='" + nextIndex + "'])[1]"
    			)

    			if (await WebUI.verifyElementPresent(nextPage, 5, FailureHandling.OPTIONAL)) {
    				await WebUI.scrollToElement(nextPage, 3)
    				await WebUI.click(nextPage)
    				await waitBlockUI(30)
    				await WebUI.delay(1)
    			} else {
    				break
    			}
    		}
    	}

    	return found
    }

